<?php require 'config.php';if(!empty($_SESSION['admin_id']))redirect('index.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$s=db()->prepare('SELECT * FROM admins WHERE username=?');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];$_SESSION['username']=$a['username'];redirect('index.php');}$error='Username atau password salah.';}?>
